package com.amit.jobagent.application;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity@Table(name="application_review_decision")class ApplicationReviewDecision{@Id UUID id;@Column(name="package_revision_id",nullable=false,updatable=false)UUID revisionId;@Enumerated(EnumType.STRING)@Column(nullable=false,updatable=false,length=30)ReviewDecisionType decision;@Column(name="actor_id",nullable=false,updatable=false,length=150)String actorId;@Column(name="actor_role",nullable=false,updatable=false,length=80)String actorRole;@Column(name="review_comment",updatable=false,length=2000)String comment;@JdbcTypeCode(SqlTypes.JSON)@Column(name="checklist_snapshot",nullable=false,updatable=false,columnDefinition="jsonb")String checklist;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="source_job_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String jobChecksum;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="source_profile_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String profileChecksum;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="source_evaluation_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String evaluationChecksum;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="artifact_manifest_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String artifactChecksum;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="validation_snapshot_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String validationChecksum;@Column(name="created_at",nullable=false,updatable=false)Instant createdAt;@Column(name="invalidated_at")Instant invalidatedAt;@Column(name="invalidation_reason",length=300)String invalidationReason;protected ApplicationReviewDecision(){}ApplicationReviewDecision(UUID revision,ReviewDecisionType decision,String actor,String role,String comment,String checklist,String job,String profile,String evaluation,String artifacts,String validation){id=UUID.randomUUID();revisionId=revision;this.decision=decision;actorId=actor;actorRole=role;this.comment=comment;this.checklist=checklist;jobChecksum=job;profileChecksum=profile;evaluationChecksum=evaluation;artifactChecksum=artifacts;validationChecksum=validation;createdAt=Instant.now();}void invalidate(String reason){if(invalidatedAt==null){invalidatedAt=Instant.now();invalidationReason=reason;}}}
